const $=s=>document.querySelector(s),key='labrescue-demo-v1';let cases=[],selected=null,history=false;try{const x=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(x))cases=x}catch{$('#error').textContent='Saved data could not be read. Existing storage has not been overwritten.'}const paths=[['From a safe distance, read the projector display. Does it show a source name or “No Signal”? Do not open or reach into equipment.','On the classroom computer, observe whether the intended presentation is open. If permitted by school policy, use the normal display menu to view the selected screen.'],['Observe the computer power indicator from its usual operating position. Do not remove covers or handle cables.','Check whether the classroom has a posted startup instruction. Read it without attempting electrical work; if uncertain, stop and contact staff.'],['Check whether the usual browser displays an offline message. Do not change network settings.','Ask whether another authorized classroom device is also offline, without sharing passwords or accessing restricted equipment.']];const issues=['Projector shows no signal','Computer will not start','Internet is unavailable'];function persist(next){try{localStorage.setItem(key,JSON.stringify(next));cases=next;$('#error').textContent='';return true}catch{$('#error').textContent='Save failed. Your change was not stored. Keep this page open and copy important details; the case was not updated.';return false}}function update(fn){const next=structuredClone(cases),x=next.find(c=>c.id===selected);fn(x);if(persist(next)){list();detail()}}function list(){const a=cases.filter(x=>history?x.resolved:!x.resolved);$('#openTab').setAttribute('aria-pressed',!history);$('#historyTab').setAttribute('aria-pressed',history);$('#list').innerHTML=a.map(c=>'<button class="case" data-case="'+c.id+'" aria-pressed="'+(c.id===selected)+'"><small>'+c.urgency+' urgency · '+(c.resolved?'Resolved':c.stopped?'Needs technician':'Open')+'</small><strong></strong><small>Open case → checks, activity & handoff</small></button>').join('')||'<div class="empty"><h2>'+(history?'No resolved cases yet.':'A clear desk. A fresh start.')+'</h2><p>'+(history?'Confirmed repairs stay available here.':'Report a problem whenever you need a next step.')+'</p></div>';a.forEach(c=>{$('[data-case="'+c.id+'"] strong').textContent=c.device+' · '+issues[c.issue];$('[data-case="'+c.id+'"]').onclick=()=>{selected=c.id;list();detail()}})}function show(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}function report(){show('<h2>What is getting in the way?</h2><form id="reportForm"><label>Supported issue<select id="issue">'+issues.map((x,i)=>'<option value="'+i+'">'+x+'</option>').join('')+'</select></label><label>Device / room reference<input id="device" required maxlength="100" placeholder="Classroom projector"></label><label>What do you see?<textarea id="symptom" required maxlength="600"></textarea></label><label>Affected lesson activity<input id="lesson" required maxlength="150" placeholder="Introducing fractions"></label><label>Urgency<select id="urgency"><option>Low</option><option selected>Medium</option><option>High</option></select></label><label>Notes (optional)<textarea id="notes" maxlength="600"></textarea></label><button class="primary">Save local case</button><p id="saveError" role="alert"></p></form>');$('#reportForm').onsubmit=e=>{e.preventDefault();const c={id:crypto.randomUUID(),issue:+$('#issue').value,device:$('#device').value,symptom:$('#symptom').value,lesson:$('#lesson').value,urgency:$('#urgency').value,notes:$('#notes').value,checks:[],stopped:false,resolved:false,activity:null,created:new Date().toISOString()};if(persist([...cases,c])){selected=c.id;history=false;$('#modal').close();list();detail()}else $('#saveError').textContent='Not saved. Browser storage is unavailable.'}}function detail(){const c=cases.find(x=>x.id===selected);if(!c)return;$('#detail').innerHTML='<span class="eyebrow">'+(c.resolved?'RESOLVED / HISTORY':'OPEN / '+c.urgency.toUpperCase()+' URGENCY')+'</span><h2 id="caseTitle"></h2><p id="symptomText"></p><div class="safe"><b>Stop if anything appears damaged, hot, wet, smoky or unsafe.</b> Keep people away and follow school emergency procedures. Do not handle cables, open equipment or attempt repairs. Contact authorized staff.</div><div id="check"></div><h3>Case history</h3><ol class="history" id="caseHistory"></ol><div id="activity"></div><div class="actions"><button id="handoff">Prepare technician handoff</button>'+(c.resolved?'':'<button id="fallback" class="primary" '+(!c.stopped&&c.checks.length<paths[c.issue].length?'hidden':'')+'>Keep my lesson going</button>')+'</div>'+(c.resolved?'<p>Teacher confirmed the repair. History remains saved locally.</p>':'<label class="confirm"><input type="checkbox" id="confirmed"> A technician has told me it is fixed, and I confirm the problem is resolved.</label><button id="resolve" disabled>Mark resolved</button>');$('#caseTitle').textContent=c.device+' / '+issues[c.issue];$('#symptomText').textContent=c.symptom+' · Lesson: '+c.lesson;$('#caseHistory').innerHTML=c.checks.map(()=>'<li></li>').join('');$('#caseHistory').querySelectorAll('li').forEach((li,i)=>li.textContent=(i+1)+'. '+c.checks[i].step+' → '+c.checks[i].outcome);if(!c.resolved&&!c.stopped&&c.checks.length<paths[c.issue].length){$('#check').innerHTML='<div class="check"><span class="eyebrow">SAFE CHECK '+(c.checks.length+1)+'</span><p>'+paths[c.issue][c.checks.length]+'</p><button data-outcome="Observed; still not working">Still not working</button><button data-outcome="Unable or unsafe to continue">Stop & escalate</button></div>';document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>update(x=>{x.checks.push({step:paths[x.issue][x.checks.length],outcome:b.dataset.outcome});if(b.dataset.outcome.startsWith('Unable'))x.stopped=true}))}else if(!c.resolved)$('#check').innerHTML='<p><b>Leave equipment as it is and ask an authorized technician.</b> Your lesson can continue with an equipment-free activity.</p>';if(c.activity){$('#activity').innerHTML='<div class="activity"><h3></h3><p></p><ol></ol><button id="printActivity">Print activity</button><button id="reuse">Reuse / edit activity</button></div>';$('#activity h3').textContent=c.activity.title;$('#activity p').textContent=c.activity.context;$('#activity ol').innerHTML=c.activity.steps.map(()=>'<li></li>').join('');$('#activity ol').querySelectorAll('li').forEach((x,i)=>x.textContent=c.activity.steps[i]);$('#printActivity').onclick=()=>printText('Saved lesson activity',activityText(c));$('#reuse').onclick=()=>fallback(c)}$('#handoff').onclick=()=>printText('Technician handoff',handoff(c));if(!c.resolved){$('#fallback').onclick=()=>fallback(c);$('#confirmed').onchange=e=>$('#resolve').disabled=!e.target.checked;$('#resolve').onclick=()=>{if($('#confirmed').checked)update(x=>x.resolved=true)}}}function activityText(c){return c.activity.title+'\n'+c.activity.context+'\n'+c.activity.steps.map((x,i)=>(i+1)+'. '+x).join('\n')}function handoff(c){return 'DEVICE: '+c.device+'\nISSUE: '+issues[c.issue]+'\nSYMPTOMS: '+c.symptom+'\nLESSON: '+c.lesson+'\nURGENCY: '+c.urgency+'\nSTATUS: '+(c.resolved?'Teacher-confirmed resolved':'Open; not confirmed repaired')+'\nNOTES: '+c.notes+'\nCHECKS:\n'+c.checks.map((x,i)=>(i+1)+'. '+x.step+'\nOutcome: '+x.outcome).join('\n')+'\nUNRESOLVED: '+(c.resolved?'None reported after teacher confirmation.':'Reported symptoms require authorized technician review. No physical fault diagnosed.')+'\n'+(c.activity?'SAVED ACTIVITY: '+activityText(c):'No fallback activity saved.')}function printText(title,text){show('<h2></h2><pre class="handoff" id="printText"></pre><button id="print">Print this document</button>');$('#modalBody h2').textContent=title;$('#printText').textContent=text;$('#print').onclick=()=>window.print()}function fallback(c){show('<h2>Keep the lesson going.</h2><p>Built-in generator. AI is off and no data leaves your browser. Avoid student names or sensitive details.</p><form id="activityForm"><label>Topic<input id="topic" maxlength="150"></label><label>Learner level<input id="level" placeholder="Mixed / adapt as needed" maxlength="100"></label><label>Available materials<input id="materials" placeholder="None required; discussion works" maxlength="150"></label><button class="primary">Create and save activity</button><p id="activityError"></p></form>');$('#topic').value=c.lesson;$('#activityForm').onsubmit=e=>{e.preventDefault();const topic=$('#topic').value.trim()||'the current lesson',level=$('#level').value.trim()||'mixed learner levels',materials=$('#materials').value.trim()||'no materials';const a={title:'Think, pair, explain: '+topic,context:'15 minutes · '+level+' · Available: '+materials+'. Uses discussion only; paper is optional. No projector, computer or internet required.',steps:['2 min: the teacher introduces one question about '+topic+' using spoken words.','3 min: learners think of one example. They may sketch on paper if available, or prepare a spoken response.','5 min: pairs explain their examples. Offer a solo reflection option and adapt the pace to '+level+'.','3 min: invite volunteers to share one connection or question.','2 min: recap the central idea and check understanding verbally. Teacher reviews suitability before use.']};const next=structuredClone(cases);next.find(x=>x.id===selected).activity=a;if(persist(next)){$('#modal').close();list();detail()}else $('#activityError').textContent='Activity not saved. Browser storage is unavailable.'}}$('#new').onclick=report;$('#heroReport').onclick=report;$('#close').onclick=()=>$('#modal').close();$('#openTab').onclick=()=>{history=false;list()};$('#historyTab').onclick=()=>{history=true;list()};list();